<script setup>


import {computed, ref} from 'vue'
import RichDescription from '../../deploy/components/RichDescription.vue'
import {prepareDescription} from '../../deploy/richDescription.js'
import {resolutionLabels, issueStatus} from '../issueFields.js'
import {mergeActivityRecords,localActivityContent} from '../activityRecords.js'
const props=defineProps({activities:Array,remote:Object,sourceUrl:String,imageResolver:Function,people:Object})
const commentsOnly=ref(false),descending=ref(false),expanded=ref(new Set())
const emit=defineEmits(['comment'])
function toggle(key){const next=new Set(expanded.value);next.has(key)?next.delete(key):next.add(key);expanded.value=next}
const actions={'release-mark':'更新了人工上线记录',opened:'创建了 Bug',created:'创建了工作项',resolved:'解决了 Bug',resolve:'解决了 Bug',closed:'关闭了 Bug',close:'关闭了 Bug',activated:'重新激活',activate:'重新激活',assigned:'变更了指派人',assignto:'变更了指派人',edited:'更新了内容',edit:'更新了内容',comment:'发表了评论',commented:'发表了评论','work-item-status':'变更了状态','work-item-assigned':'变更了负责人','work-item-updated':'更新了工作项','release-intent':'更新了上线意图','delivery-ownership':'更新了交付归属','change-created':'新增了交付内容','change-updated':'保存了交付草稿','change-ready':'校验并就绪了交付内容'}
const fields={resolution:'修复方案',status:'状态',assignedTo:'指派给',resolvedBy:'解决人',resolvedBuild:'解决版本',title:'标题',severity:'严重程度',pri:'优先级',steps:'说明',activatedDate:'激活时间',activatedCount:'激活次数',resolvedDate:'解决时间',closedDate:'关闭时间',openedDate:'创建时间',lastEditedDate:'修改时间',lastEditedBy:'修改人',openedBy:'创建人',closedBy:'关闭人',confirmed:'是否确认',deadline:'截止日期',type:'类型',product:'产品',project:'项目',module:'模块',openedBuild:'影响版本',duplicateBug:'重复 Bug',keywords:'关键词'}
const normalized=v=>v===undefined||v===null||/^\s*$|^0000-00-00(?:[ T]00:00:00)?$/.test(String(v))?'':String(v)

function time(value){if(typeof value==='number')return value*1000;const date=Date.parse(String(value||'').replace(' ','T'));return Number.isFinite(date)?date:0}
const entries=computed(()=>{
 const records=mergeActivityRecords((props.activities||[]).map(a=>({...a,content:localActivityContent(a)})),props.remote,props.people)
 return records.map(a=>({...a,action:actions[a.kind?.toLowerCase()]||a.kind,at:time(a.date),history:a.history.filter(h=>normalized(h.old)!==normalized(h.new)),technical:props.activities?.find(raw=>'local-'+raw.id===a.key&&['release-mark','release-intent','delivery-ownership','change-created','change-updated','change-ready','work-item-updated','work-item-status','work-item-assigned'].includes(raw.kind))?.content,hasContent:!!prepareDescription(a.content,props.sourceUrl,a.format).text.trim()})).sort((a,b)=>(descending.value?b.at-a.at:a.at-b.at)||a.key.localeCompare(b.key))
})
const visible=computed(()=>entries.value.filter(a=>!commentsOnly.value||(a.hasContent&&!a.technical)))
function value(field,v){if(normalized(v)==='')return '未填写';if(field==='resolution')return props.remote?.resolutions?.[v]||resolutionLabels[v]||v;if(field==='status')return props.remote?issueStatus({external_status:v}):({open:'待处理',active:'处理中',resolved:'已解决',closed:'已关闭'}[v]||v);if(['resolvedBuild','openedBuild'].includes(field))return props.remote?.builds?.[v]||(v==='trunk'?'主干':v);if(['assignedTo','resolvedBy','openedBy','closedBy','lastEditedBy'].includes(field))return props.remote?.users?.[v]||v;return String(v)}
function resolution(a){const code=a.history.find(h=>h.field==='resolution')?.new;return code&&(props.remote?.resolutions?.[code]||resolutionLabels[code])||''}
const stamp=a=>a.at?new Date(a.at).toLocaleString('zh-CN',{hour12:false}):a.date||'时间未知'



import {Accordion,AccordionContent,AccordionItem,AccordionTrigger,Button,Tabs,TabsList,TabsTrigger} from '../../shared/shadcn-ui.js'
</script>
<template><section aria-label="评论与活动" class="activity-timeline"><div class="activity-heading"><h3>历史记录</h3><Button :aria-label="descending?'按时间正序':'按时间倒序'" :title="descending?'当前最新在前':'当前最早在前'" @click="descending=!descending" class="order-toggle" variant="ghost" size="sm" type="button">{{descending?'↓':'↑'}}</Button><Tabs aria-label="活动筛选" :model-value="commentsOnly?'comments':'all'" @update:model-value="(value=>commentsOnly=value==='comments')($event)"><TabsList class="h-auto! flex-wrap gap-y-1 [&>[data-slot=tabs-trigger]]:h-7"><TabsTrigger :value="&quot;all&quot;">全部活动</TabsTrigger><TabsTrigger :value="&quot;comments&quot;">只看评论</TabsTrigger></TabsList></Tabs><Button @click="emit('comment')" class="add-comment" variant="ghost" size="default" type="button">添加备注</Button></div><ol v-if="visible.length" class="activity-list"><li v-for="(a,index) in visible" :key="a.key" class="activity-entry"><div :title="a.source?'来自禅道':'来自本平台'" class="activity-meta"><span class="activity-number">{{index+1}}.</span><time>{{stamp(a)}}</time><span>，由 <strong>{{a.actor||'未知用户'}}</strong> {{a.action}}<template v-if="resolution(a)">，方案为 <strong>{{resolution(a)}}</strong></template>。</span></div><div class="activity-content"><div v-if="a.hasContent" class="activity-comment"><RichDescription :content="a.content" :format="a.format" :source-url="sourceUrl" :image-resolver="a.source?imageResolver:undefined" full compact thumbnails title="评论内容"/></div><Accordion v-if="a.technical" type="single" collapsible class="mt-2 text-xs text-muted-foreground"><AccordionItem value="raw"><AccordionTrigger>原始记录</AccordionTrigger><AccordionContent><pre class="whitespace-pre-wrap break-words">{{a.technical}}</pre></AccordionContent></AccordionItem></Accordion><Accordion v-if="a.history.length" class="activity-fields" type="multiple" :model-value="(expanded.has(a.key)?['fields']:[]||[]).map(String)" @update:model-value="(()=>toggle(a.key))($event)"><AccordionItem :value="String(&quot;fields&quot;)"><AccordionTrigger>详细设置</AccordionTrigger><AccordionContent force-mount v-show="!(!(expanded.has(a.key)?['fields']:[]||[]).map(String).includes(String(&quot;fields&quot;)))"><ul :id="'history-'+a.key" class="activity-history"><li v-for="(h,i) in a.history" :key="i"><span>{{fields[h.field]||h.field}}</span>：<span class="history-old">{{value(h.field,h.old)}}</span> → <span>{{value(h.field,h.new)}}</span></li></ul></AccordionContent></AccordionItem></Accordion></div></li></ol><p v-else class="r-muted">{{commentsOnly?'暂无评论。':'暂无活动记录。'}}</p></section></template>
<style scoped>.activity-timeline{margin-top:24px}.activity-heading{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:10px}.activity-heading h3{font-size:1rem;margin:0}.activity-heading .add-comment{margin-left:auto}.activity-list{list-style:none;padding:0;margin:0}.activity-entry{padding:5px 0}.activity-meta{display:flex;align-items:baseline;flex-wrap:wrap;line-height:1.8;font-size:.875rem;color:var(--text)}.activity-number{min-width:20px}.activity-meta strong{font-weight:600}.activity-meta time{white-space:nowrap}.activity-content{margin-left:20px;min-width:0}.activity-comment{margin-top:5px;padding:8px 12px;background:var(--panel2);border:1px solid var(--border);overflow-wrap:anywhere}.activity-comment :deep(.description-body p:last-child){margin-bottom:0}.activity-history{list-style:none;margin:6px 0 0;padding:8px 12px;max-height:280px;overflow:auto;background:var(--panel2);border:1px solid var(--border);color:var(--muted-foreground);font-size:.75rem}.activity-history li{margin:4px 0;overflow-wrap:anywhere;max-height:120px;overflow:auto}.history-old{opacity:.75}@media(max-width:700px){.activity-meta{font-size:.75rem}.activity-heading{gap:6px}.activity-content{margin-left:16px}}@media(pointer:coarse){.activity-heading .order-toggle,.activity-heading .add-comment{min-width:44px}}</style>
